const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Approximate bounding box for Northern Ethiopia
  const roi_north = ee.Geometry.Polygon([
    [36.0, 10.0],
    [42.0, 10.0],
    [42.0, 14.0],
    [36.0, 14.0],
    [36.0, 10.0]
  ]);

  // Approximate bounding box for Southern Ethiopia
  const roi_south = ee.Geometry.Polygon([
    [36.0, 3.0],
    [42.0, 3.0],
    [42.0, 7.0],
    [36.0, 7.0],
    [36.0, 3.0]
  ]);

  const anomaly_start_date = '2021-10-01';
  const anomaly_end_date = '2021-11-30';
  const lta_start_date = '2000-10-01';
  const lta_end_date = '2013-11-30';
  const scale = 5566; // CHIRPS original resolution in meters (~0.05 degrees)

  // 2. Data Acquisition
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/MONTHLY');

  // Filter for the long-term average (LTA) period
  const lta_collection = chirps
    .filterDate(lta_start_date, lta_end_date)
    .filter(ee.Filter.calendarRange(10, 11, 'month')); // October and November

  // Filter for the anomaly period
  const anomaly_collection = chirps
    .filterDate(anomaly_start_date, anomaly_end_date);

  // Check collection sizes
  const lta_size = await lta_collection.size().getInfo();
  const anomaly_size = await anomaly_collection.size().getInfo();

  if (lta_size === 0 || anomaly_size === 0) {
    console.log(`LTA collection size: ${lta_size}, Anomaly collection size: ${anomaly_size}`);
    console.log("C1");
    return;
  }
  console.log(`LTA images (Oct-Nov 2000-2013): ${lta_size}`);
  console.log(`Anomaly images (Oct-Nov 2021): ${anomaly_size}`);

  // Calculate LTA mean precipitation
  const lta_mean_north = await lta_collection.mean().reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi_north,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const lta_mean_south = await lta_collection.mean().reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi_south,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // Calculate anomaly period mean precipitation
  const anomaly_mean_north = await anomaly_collection.mean().reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi_north,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const anomaly_mean_south = await anomaly_collection.mean().reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi_south,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // 3. Validation for C3 (Calculation Failure)
  if (lta_mean_north === null || lta_mean_south === null ||
      anomaly_mean_north === null || anomaly_mean_south === null) {
    console.log("C3");
    return;
  }

  // Calculate anomalies (Current - LTA)
  const anomaly_val_north = anomaly_mean_north - lta_mean_north;
  const anomaly_val_south = anomaly_mean_south - lta_mean_south;

  console.log(`North LTA Avg (mm): ${lta_mean_north.toFixed(2)}`);
  console.log(`North 2021 Avg (mm): ${anomaly_mean_north.toFixed(2)}`);
  console.log(`South LTA Avg (mm): ${lta_mean_south.toFixed(2)}`);
  console.log(`South 2021 Avg (mm): ${anomaly_mean_south.toFixed(2)}`);

  console.log(`North Anomaly (mm): ${anomaly_val_north.toFixed(2)}`);
  console.log(`South Anomaly (mm): ${anomaly_val_south.toFixed(2)}`);

  // Compare anomalies: "did southern Ethiopia receive less rainfall than northern Ethiopia relative its long-term average"
  // This means anomaly_val_south < anomaly_val_north
  if (anomaly_val_south < anomaly_val_north) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
